const mdlOf=i=>{if(i===2){const st=S.promoted?5:S.stt===2?4:S.stt===1?3:S.mdlReq2?1:0;return Object.assign({step:st,cand:0,gs:true},S.mdl&&S.mdl[2]||{},{step:Math.max(st,(S.mdl&&S.mdl[2]&&S.mdl[2].step)||0)});}return Object.assign({step:0,cand:0,gs:false,evalOk:false,canaryOk:false,type:'model',appr:null},S.mdl&&S.mdl[i]||{});};
