   const req=`<div class="box"><h4>이 단계의 기본 요건 <span class="ft" style="margin:0;font-weight:600">· 담당 : ${D.MREQ[step][1]}</span></h4><p class="nt" style="font-size:12.5px">${D.MREQ[step][0]}</p></div>`;
