  const T=D.SPLIT;const leak=S.dzLeak;
  const tblS=(k,hit)=>{const t=T[k];return `<div class="box" style="border-color:${hit?'#f3c1c1':'#d4dcea'};background:${hit?'#fff8f8':'#fff'}"><h4><span class="sp">${t.name}</span>${hit?chipC('유출 가정','red'):chipC('안전','green')}</h4><div class="gt" style="margin:0 0 8px"><div class="gt__hd" style="grid-template-columns:repeat(${t.cols.length},minmax(0,1fr))">${t.cols.map(c=>`<div>${c}</div>`).join('')}</div>${t.rows.map(r=>`<div class="gt__r" style="grid-template-columns:repeat(${t.cols.length},minmax(0,1fr));font-size:12px;${hit?'color:#7a1f1f':''}">${r.map(x=>`<div>${x}</div>`).join('')}</div>`).join('')}</div>${kv([['암호화 · 계정',t.enc],['읽는 주체',t.who]],84,1)}</div>`;};
